"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import { useParams } from "next/router"; // Pour récupérer l'ID du groupe depuis l'URL

export default function EditGroupe() {
  const [groupe, setGroupe] = useState(null);
  const [tuteurs, setTuteurs] = useState([]);
  const [sujets, setSujets] = useState([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const { idGroupe } = useParams(); // Récupération de l'ID du groupe depuis l'URL

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [groupeResponse, tuteursResponse, sujetsResponse] = await Promise.all([
        axios.get(`http://localhost:5000/api/groupes/${idGroupe}`),
        axios.get("http://localhost:5000/api/tuteurs"),
        axios.get("http://localhost:5000/api/sujets"),
      ]);

      setGroupe(groupeResponse.data);
      setTuteurs(tuteursResponse.data);
      setSujets(sujetsResponse.data);
    } catch (error) {
      console.error("Erreur lors du chargement des données", error);
      alert("Erreur lors du chargement des données");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (field, value) => {
    setGroupe((prevGroupe) => ({
      ...prevGroupe,
      [field]: value,
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    try {
      const updatedGroupe = await axios.put(`http://localhost:5000/api/groupes/${idGroupe}`, groupe);
      alert("Groupe mis à jour avec succès!");
      router.push("/gestiongroupes"); // Rediriger après la mise à jour
    } catch (error) {
      console.error("Erreur lors de la mise à jour", error);
      alert("Erreur lors de la mise à jour du groupe");
    }
  };

  if (loading) {
    return <div>Chargement...</div>;
  }

  return (
    <div className="container mx-auto p-6">
      <h2 className="text-2xl font-bold mb-4">Modifier le Groupe</h2>
      <form onSubmit={handleSubmit}>
        <div className="mb-4">
          <label htmlFor="nomGroupe" className="block text-sm font-semibold">Nom du groupe</label>
          <input
            type="text"
            id="nomGroupe"
            value={groupe.nomGroupe}
            onChange={(e) => handleChange("nomGroupe", e.target.value)}
            className="border p-2 w-full rounded"
          />
        </div>

        <div className="mb-4">
          <label htmlFor="tuteur" className="block text-sm font-semibold">Tuteur</label>
          <select
            id="tuteur"
            value={groupe.tuteur ? groupe.tuteur.idTuteur : ""}
            onChange={(e) => handleChange("tuteur", tuteurs.find(t => t.idTuteur === e.target.value))}
            className="border p-2 w-full rounded"
          >
            <option value="">Sélectionner un tuteur</option>
            {tuteurs.map((tuteur) => (
              <option key={tuteur.idTuteur} value={tuteur.idTuteur}>
                {tuteur.nom} {tuteur.prenom}
              </option>
            ))}
          </select>
        </div>

        <div className="mb-4">
          <label htmlFor="sujet" className="block text-sm font-semibold">Sujet</label>
          <select
            id="sujet"
            value={groupe.sujet ? groupe.sujet.idSujet : ""}
            onChange={(e) => handleChange("sujet", sujets.find(s => s.idSujet === e.target.value))}
            className="border p-2 w-full rounded"
          >
            <option value="">Sélectionner un sujet</option>
            {sujets.map((sujet) => (
              <option key={sujet.idSujet} value={sujet.idSujet}>
                {sujet.titre}
              </option>
            ))}
          </select>
        </div>

        <div className="mb-4">
          <button type="submit" className="bg-blue-500 text-white px-4 py-2 rounded">
            Enregistrer les modifications
          </button>
        </div>
      </form>
    </div>
  );
}
